import { setup, types } from 'xstate';

const checkoutMachine = setup({
  schemas: {
    context: types<{ attempts: number }>(),
    events: {
      submit: types<{}>(),
      'payment.succeeded': types<{}>(),
      'payment.failed': types<{ reason: string }>(),
      retry: types<{}>(),
      cancel: types<{}>()
    }
  }
}).createMachine({
  id: 'checkout',
  context: { attempts: 0 },
  initial: 'reviewing',
  states: {
    reviewing: {
      on: { submit: { target: 'paying' }, cancel: { target: 'cancelled' } }
    },
    paying: {
      timeout: 30_000,
      onTimeout: { target: 'failed' },
      on: {
        'payment.succeeded': { target: 'confirmed' },
        'payment.failed': { target: 'failed' }
      }
    },
    failed: {
      on: {
        retry: ({ context }) => {
          if (context.attempts >= 3) return;
          return { target: 'paying', context: { attempts: context.attempts + 1 } };
        },
        cancel: { target: 'cancelled' }
      }
    },
    confirmed: { type: 'final' },
    cancelled: { type: 'final' }
  }
});
export { checkoutMachine };
